pub fn note_commitment(owner_key: &Digest, value: u32, asset_id: M31, salt: &Digest) -> Digest {
    note_commitment_with(owner_key, value, asset_id, salt, &mut hash_fields)
}

pub fn pool_v1_note_commitment(
    owner_key: &Digest,
    value: u32,
    asset_id: M31,
    salt: &Digest,
) -> Digest {
    note_commitment(owner_key, value, asset_id, salt)
}

pub(crate) fn append_roots_unchecked(data: &mut [u8], header: RootPageHeaderV1, roots: &[Digest]) {
    debug_assert!(usize::from(header.filled) + roots.len() <= POOL_V1_ROOT_HISTORY_CAPACITY);
    for (offset, root) in roots.iter().enumerate() {
        let slot = usize::from(header.filled) + offset;
        let start = PAGE_ROOTS_OFFSET + slot * 32;
        data[start..start + 32].copy_from_slice(&encode_digest_canonical(root));
    }
    let filled = header.filled + roots.len() as u16;
    data[PAGE_FILLED_OFFSET..58].copy_from_slice(&filled.to_le_bytes());
}

pub fn pool_v1_root_page_address(
    program_id: &Pubkey,
    pool: &Pubkey,
    page_number: u64,
) -> (Pubkey, u8) {
    let page_number_bytes = page_number.to_le_bytes();
    Pubkey::find_program_address(
        &[
            POOL_V1_ROOT_HISTORY_PAGE_SEED,
            pool.as_ref(),
            &page_number_bytes,
        ],
        program_id,
    )
}

pub fn leaf_digest(&self) -> Result<Digest, PoolV1PairLeafErrorV1> {
    self.validate()?;
    Ok(pool_v1_tree_parent(
        &self.first_commitment,
        &self.second_commitment,
    ))
}

pub fn single_output(first_commitment: Digest) -> Result<Self, PoolV1PairLeafErrorV1> {
    let result = Self {
        first_commitment,
        second_occupied: M31::ZERO,
        second_commitment: [M31::ZERO; 8],
        second_occupancy_inverse: M31::ZERO,
    };
    result.validate()?;
    Ok(result)
}

pub fn pool_v1_pair_forest_deposit_lane_v1(
    commitment: &Digest,
) -> Result<u8, PoolV1PairForestAccountErrorV1> {
    if !digest_is_canonical(commitment) {
        return Err(PoolV1PairForestAccountErrorV1::NonCanonicalDigest);
    }
    Ok(first_canonical_byte(commitment) & 7)
}

fn decode_deposit_lane_box_v1(
    program_id: &Pubkey,
    master: &Pubkey,
    lane_id: u8,
    lane_account: &AccountInfo<'_>,
) -> Result<Box<PoolV1PairForestLaneStateV1>, ProgramError> {
    #[cfg(feature = "pair-forest-deposit-invariant-audit")]
    return Ok(Box::new(decode_lane_account_from_program_invariant_v1(
        program_id,
        master,
        lane_id,
        lane_account,
        true,
    )?));

    #[cfg(not(feature = "pair-forest-deposit-invariant-audit"))]
    Ok(Box::new(decode_lane_account(
        program_id,
        master,
        lane_id,
        lane_account,
        true,
    )?))
}

fn prepare_deposit_append_v1(
    lane: &PoolV1PairForestLaneStateV1,
    lane_id: u8,
    pair_leaf: Digest,
) -> Result<
    (
        AppendOneV1,
        Box<[u8; POOL_V1_PAIR_FOREST_LANE_ACCOUNT_BYTES]>,
    ),
    ProgramError,
> {
    #[cfg(not(feature = "pair-forest-deposit-invariant-audit"))]
    let (next_tree, append) = lane
        .tree
        .append_one_with_empty_roots(pair_leaf, &POOL_V1_PAIR_EMPTY_ROOTS)
        .map_err(|_| PoolV1ProgramError::StateHistoryMismatch)?;
    #[cfg(feature = "pair-forest-deposit-invariant-audit")]
    let (next_tree, append) = append_pair_leaf_from_program_invariant_v1(&lane.tree, pair_leaf)?;
    let next_lane = Box::new(PoolV1PairForestLaneStateV1 {
        bump: lane.bump,
        master: lane.master,
        lane_id,
        tree: next_tree,
    });
    #[cfg(not(feature = "pair-forest-deposit-invariant-audit"))]
    let next_lane_image = Box::new(
        encode_pool_v1_pair_forest_lane_state_v1(&next_lane, &POOL_V1_PAIR_EMPTY_ROOTS)
            .map_err(|_| PoolV1ProgramError::StateHistoryMismatch)?,
    );
    #[cfg(feature = "pair-forest-deposit-invariant-audit")]
    let next_lane_image = Box::new(encode_lane_from_authenticated_result_v1(&next_lane)?);
    Ok((append, next_lane_image))
}

fn require_exact_account_count(accounts: &[AccountInfo<'_>], expected: usize) -> ProgramResult {
    if accounts.len() != expected {
        return Err(if accounts.len() < expected {
            ProgramError::NotEnoughAccountKeys
        } else {
            ProgramError::InvalidArgument
        });
    }
    Ok(())
}

pub(crate) fn require_payer_and_system_program(
    payer: &AccountInfo<'_>,
    system_program_account: &AccountInfo<'_>,
) -> ProgramResult {
    if !payer.is_signer
        || !payer.is_writable
        || payer.executable
        || payer.owner != &system_program::id()
    {
        return Err(PoolV1ProgramError::InvalidPayer.into());
    }
    if system_program_account.key != &system_program::id()
        || system_program_account.owner != &native_loader::id()
        || !system_program_account.executable
        || system_program_account.is_signer
        || system_program_account.is_writable
    {
        return Err(PoolV1ProgramError::InvalidSystemProgram.into());
    }
    Ok(())
}

pub(crate) fn require_token_program_account(account: &AccountInfo<'_>) -> ProgramResult {
    if account.key != &LEGACY_SPL_TOKEN_PROGRAM_ID
        || !account.executable
        || account.is_signer
        || account.is_writable
        || !supported_program_loader(account.owner)
    {
        return Err(PoolV1ProgramError::InvalidTokenProgram.into());
    }
    Ok(())
}
